let revealObserver;
function setupProjectReveal() {
  revealObserver?.disconnect();
  const els = $$('#proyek .sec-head,#proyek .chips,#proyek #count,#proyek .row');
  if (reduce) {
    els.forEach((el) => el.classList.add('is-visible'));
    return;
  }
  revealObserver = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;
        const t = entry.target;
        t.classList.add('is-visible');
        revealObserver.unobserve(t);
        setTimeout(() => {
          t.style.transitionDelay = '';
          if (t.classList.contains('row')) t.classList.add('revealed');
        }, 1000); // hand hover back to the normal fast transition
      });
    },
    { rootMargin: '0px 0px -10% 0px', threshold: 0.08 },
  );
  els.forEach((el, i) => {
    el.style.transitionDelay = `${Math.min(i, 8) * 55}ms`;
    revealObserver.observe(el);
  });
}
