    // Re-entering while closing cancels every exit animation and restarts the reveal.
    if (card._closing) {
      cancelSkillAnimations(card);
      card.classList.add('open');
      setSkillToggle(card, true);
      markSkillMoving(card);
      playWords(card);
      return;
    }
    if (card.classList.contains('open')) return;
    cancelSkillAnimations(card);
    card.classList.add('open');
    setSkillToggle(card, true);
    markSkillMoving(card);
    playWords(card);
